from pathlib import Path
import pandas as pd

def latest_revision_file(base, patterns):
    if isinstance(patterns, str):
        patterns=[patterns]
    matches=[]
    for pattern in patterns:
        matches.extend(base.glob(pattern))
    if not matches:
        return None
    def sort_key(path):
        revisions=[part for part in path.parts if part.startswith('#') and part.endswith('#')]
        revision=revisions[-1] if revisions else ''
        return revision, str(path)
    matches.sort(key=sort_key)
    return matches[-1]

bwm=pd.read_csv('code/code_zhang2025/data/bwm_release.csv')
kept=0
for eid, group in bwm.groupby('eid', sort=False):
    first=group.iloc[0]
    alf=Path('data/one_cache')/first['lab']/'Subjects'/first['subject']/first['date']/f"{int(first['session_number']):03d}"/'alf'
    found=False
    for view in ('left','right'):
        me=latest_revision_file(alf, f'#*/{view}Camera.ROIMotionEnergy.npy')
        t=latest_revision_file(alf, [f'_ibl_{view}Camera.times.npy', f'#*/_ibl_{view}Camera.times.npy'])
        if me is not None and t is not None:
            found=True
            break
    if found:
        kept += 1
print('motion energy sessions with times', kept)
